/* ═══════════════════════════════════════════════════════════════════════════════════
   REPRODUTOR DE AUDIO - ESMAECIMENTO CORRIGIDO
   ═══════════════════════════════════════════════════════════════════════════════════ */

function setupAudioFadeOut() {
  // Encontra todos os players de audio
  const audioPlayers = document.querySelectorAll('audio, [data-audio-player]');
  
  audioPlayers.forEach(player => {
    // Adiciona listener ao evento de pausa para fade out
    player.addEventListener('pause', function() {
      fadeOutAudio(this);
    });
    
    // Adiciona listener ao evento de ending para fade out
    player.addEventListener('ended', function() {
      fadeOutAudio(this);
    });
  });
}

// Função de esmaecimento com duração configurável (em ms)
// CONFIGURAÇÃO MANUAL: Alterar o valor de 'fadeDuration' abaixo para ajustar tempo
const AUDIO_FADE_DURATION = 1500; // Duração do fade out em milissegundos (padrão: 1.5 segundos)

function fadeOutAudio(audioElement) {
  if (!audioElement) return;
  
  // Se já está esmaecendo, não inicia outro
  if (audioElement._fading) return;
  
  audioElement._fading = true;
  
  // Se o volume já é 0, apenas deixa mudo
  if (audioElement.volume <= 0) {
    audioElement.muted = true;
    audioElement._fading = false;
    return;
  }
  
  const startVolume = audioElement.volume;
  const startTime = Date.now();
  
  const fade = () => {
    const elapsed = Date.now() - startTime;
    const progress = Math.min(elapsed / AUDIO_FADE_DURATION, 1);
    
    // Cálculo suave do volume (easing out)
    audioElement.volume = startVolume * (1 - progress);
    
    if (progress < 1) {
      requestAnimationFrame(fade);
    } else {
      audioElement.volume = 0;
      audioElement.muted = true;
      audioElement._fading = false;
    }
  };
  
  requestAnimationFrame(fade);
}

// Inicializa fade out quando o DOM estiver pronto
document.addEventListener('DOMContentLoaded', setupAudioFadeOut);
// Também monitora alterações dinâmicas no DOM
const audioObserver = new MutationObserver(setupAudioFadeOut);
audioObserver.observe(document.body, { childList: true, subtree: true });

/* ═══════════════════════════════════════════════════════════════════════════════════
   CONTROLES DE NAVEGAÇÃO DE AULA - LAYOUT MELHORADO E CENTRALIZADO
   ═══════════════════════════════════════════════════════════════════════════════════ */

function setupLessonNavigation() {
  // Cria estilo CSS para os botões de navegação
  const style = document.createElement('style');
  style.textContent = `
    /* Contenedor de navegação de aulas - CENTRALIZADO */
    .gdi-lesson-nav-container {
      display: flex;
      justify-content: center;
      align-items: center;
      gap: 20px;
      padding: 20px;
      margin: 20px 0;
      background: rgba(255, 255, 255, 0.05);
      border-radius: 12px;
      backdrop-filter: blur(10px);
      box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
    }
    
    /* Botões de navegação - Design profissional */
    .gdi-lesson-nav-btn {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 12px 24px;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      color: white;
      border: none;
      border-radius: 8px;
      font-size: 16px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);
      text-decoration: none;
      white-space: nowrap;
    }
    
    .gdi-lesson-nav-btn:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 20px rgba(102, 126, 234, 0.5);
      background: linear-gradient(135deg, #764ba2 0%, #667eea 100%);
    }
    
    .gdi-lesson-nav-btn:active {
      transform: translateY(0px);
      box-shadow: 0 2px 8px rgba(102, 126, 234, 0.3);
    }
    
    .gdi-lesson-nav-btn:disabled {
      opacity: 0.5;
      cursor: not-allowed;
      transform: none;
    }
    
    .gdi-lesson-nav-btn i {
      font-size: 18px;
    }
    
    /* Indicador de aula atual */
    .gdi-lesson-counter {
      padding: 8px 16px;
      background: rgba(102, 126, 234, 0.1);
      border: 1px solid rgba(102, 126, 234, 0.3);
      border-radius: 6px;
      font-weight: 600;
      color: #667eea;
      font-size: 14px;
      min-width: 120px;
      text-align: center;
    }
    
    /* Responsivo */
    @media (max-width: 768px) {
      .gdi-lesson-nav-container {
        gap: 12px;
        padding: 16px;
      }
      
      .gdi-lesson-nav-btn {
        padding: 10px 16px;
        font-size: 14px;
      }
      
      .gdi-lesson-nav-btn span {
        display: none;
      }
    }
  `;
  document.head.appendChild(style);
}

// Inicializa navegação de aulas
document.addEventListener('DOMContentLoaded', setupLessonNavigation);

